 2) require_cmd vnstat && vnstat -d;; 3) require_cmd vnstat && vnstat -m;;
 4) require_cmd vnstat && vnstat -l;; 5) require_cmd vnstat && vnstat;; 0) return;; *) err "$(L '无效选择' 'Invalid choice')";; esac
