# Quota users run isolated direct Reality/HY2 cores, so their totals are per account.
users_guard(){
 local unit=skybyte-users.service file
 if [[ -e $SYSTEMD_DIR/$unit || -L $SYSTEMD_DIR/$unit ]]; then
  if [[ -L $SYSTEMD_DIR/$unit ]] || ! grep -Fxq 'Description=SKYBYTE managed user quota supervisor' "$SYSTEMD_DIR/$unit" || ! grep -Fxq "ExecStart=/bin/bash $MANAGER_BIN --users-watch" "$SYSTEMD_DIR/$unit"; then err "$(L '用户服务归属异常' 'User service ownership mismatch')"; return 1; fi
 fi
 for file in users.json users users.lock users-worker.lock; do
  [[ ! -L $BASE/$file ]] || { err "$(L '用户文件是符号链接，拒绝修改' 'User file is a symlink; refusing changes')"; return 1; }
 done
 if [[ ( -f $BASE/users.json || ${1:-} == setup ) && ( -e $MANAGER_BIN || -L $MANAGER_BIN ) ]]; then
  if [[ -L $MANAGER_BIN ]] || ! grep -q '^# SKYBYTE Manager V2.1 community manager;' "$MANAGER_BIN"; then err "$(L '管理脚本归属异常' 'Manager executable ownership mismatch')"; return 1; fi
 fi
 if [[ -f $BASE/users.json ]]; then users_engine guard || return 1; fi
}
users_setup_service(){
 users_guard setup || return 1
 if [[ ! $SCRIPT_PATH -ef $MANAGER_BIN ]]; then command install -m 700 "$SCRIPT_PATH" "$MANAGER_BIN" || return 1; fi
 cat > "$SYSTEMD_DIR/skybyte-users.service" <<EOF
[Unit]
Description=SKYBYTE managed user quota supervisor
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=/bin/bash $MANAGER_BIN --users-watch
Restart=on-failure
RestartSec=5
KillMode=mixed
TimeoutStopSec=30
LimitNOFILE=1048576
UMask=0077
[Install]
WantedBy=multi-user.target
EOF
 systemctl daemon-reload
}
users_firewall_allow(){
 [[ -f $BASE/users.json ]] || return 0
 users_guard || return 1
 local rules rule
 rules=$(users_engine firewall_rules "${1:-}") || return 1
 while IFS= read -r rule; do [[ -z $rule ]] || ufw allow "$rule" || return 1; done <<<"$rules"
}
users_start(){
 users_guard || return 1
 if ! python3 - "$BASE/users.json" <<'PY'
import json,sys
sys.exit(0 if json.load(open(sys.argv[1])).get('supervisor_enabled',True) else 1)
PY
 then return 0; fi
 users_setup_service && users_engine validate "$BIN" && systemctl enable --now skybyte-users.service
}
users_stop(){ users_guard || return 1; if [[ -f $SYSTEMD_DIR/skybyte-users.service ]]; then systemctl stop skybyte-users.service; fi; }
users_restore_snapshot(){
 local path=$1 limit
 users_guard && users_stop || return 1
 if [[ -f $path/users.json ]]; then
  if [[ ! -f $BASE/users.json ]]; then
   limit=$(python3 - "$path/users.json" <<'PY'
import json,sys
print(json.load(open(sys.argv[1]))['limit'])
PY
 ) || return 1
   users_engine init "$limit" || return 1
  fi
  users_engine restore "$path" || return 1
  users_start || return 1
 elif [[ -f $BASE/users.json ]]; then users_start || return 1; fi
}
users_remove(){
 users_guard || return 1
 [[ -f $BASE/users.json || -f $SYSTEMD_DIR/skybyte-users.service ]] || return 0
 if [[ -f $SYSTEMD_DIR/skybyte-users.service ]]; then systemctl disable --now skybyte-users.service || return 1; rm -f "$SYSTEMD_DIR/skybyte-users.service"; fi
 if [[ -f $BASE/users.json ]]; then users_engine cleanup || return 1; fi
 rm -f "$BASE/users.lock" "$BASE/users-worker.lock"
}
users_export(){
 local id=$1 path
 local BASE=$BASE META=$META CONF=$CONF
 path=$(users_engine export "$id") || return 1
 BASE=$path; META=$path/state.json; CONF=$path/server.json; exports
}
users_qr(){
 local id=$1 path
 local BASE=$BASE META=$META CONF=$CONF
 path=$(users_engine export "$id") || return 1
 BASE=$path; META=$path/state.json; CONF=$path/server.json; shadowrocket_qr
}
users_manager(){
 check_owned && users_guard || return 1
 warn "$(L '仅新建的受限账户执行人数、流量和到期限制。原管理员节点及 Argo 不受此配额管理。每人独立进程/端口；请放行云防火墙对应端口。' 'Limits apply only to new managed accounts. Existing admin nodes and Argo are outside these quotas. Each account uses its own process/port; allow those provider firewall ports.')"
 local choice max name quota days id action port snap
 while :; do
  printf '%s' "$GREEN"
  prompt_options '1 初始化用户管理  2 添加用户  3 查看用量  4 修改流量额度' '1 Initialize  2 Add account  3 Usage  4 Change quota'
  prompt_options '5 启用/禁用用户  6 删除用户  7 重置流量  8 设置人数上限' '5 Enable/disable  6 Delete  7 Reset usage  8 Set account limit'
  prompt_options '9 用户节点与二维码  10 服务状态  11 启动用户服务  12 停止用户服务' '9 User exports/QR  10 Status  11 Start supervisor  12 Stop supervisor'
  prompt_options '13 修改有效期  14 用户故障诊断  15 资源占用  0 返回' '13 Change validity  14 User diagnostics  15 Resources  0 Back'
  printf '%s' "$RESET"
  prompt_read '> ' choice || return 0
  [[ $choice != 0 ]] || return 0
  if [[ $choice != 1 && ! -f $BASE/users.json ]]; then err "$(L '请先初始化用户管理' 'Initialize user management first')"; continue; fi
  case $choice in
   1)
    [[ ! -f $BASE/users.json ]] || { err "$(L '用户管理已存在，拒绝覆盖' 'User management exists; refusing overwrite')"; continue; }
    prompt_read "$(L '最多用户数 [10]（1-100）：' 'Maximum accounts [10] (1-100): ')" max || return 0
    max=${max:-10}
    if ! valid_port "$max" || ! (( 10#$max<=100 )); then err "$(L '账户上限须为1至100' 'Account limit must be 1-100')"; return 1; fi
    users_guard setup || return 1
    confirm "$(L '初始化独立用户服务？已有节点将保留。' 'Initialize isolated user services? Existing nodes remain.')" || continue
    snap=$(backup) || return 1
    users_engine init "$max" && users_start || return 1
    say "初始化完成；备份：$snap" "Initialized; backup: $snap";;
   2)
    prompt_read "$(L '用户名：' 'User name: ')" name || return 0
    prompt_read "$(L '总流量 GiB [100]：' 'Total quota GiB [100]: ')" quota || return 0
    prompt_read "$(L '有效天数 [30]：' 'Validity days [30]: ')" days || return 0
    id=$(users_engine add "$name" "${quota:-100}" "${days:-30}") || return 1
    port=$(python3 - "$BASE/users.json" "$id" <<'PY'
import json,sys
print(next(u['port'] for u in json.load(open(sys.argv[1]))['users'] if u['id']==sys.argv[2]))
PY
 ) || return 1
    if command -v ufw >/dev/null && LC_ALL=C ufw status | grep -q '^Status: active'; then
     users_firewall_allow "$id" || return 1
    fi
    users_start || return 1
    ok "$(L '已创建用户 ID：' 'Created account ID: ')$id"
    warn "$(L "请在云防火墙放行节点端口 ${port}；控制 API 仅监听本机，不应公开。" "Allow node port $port in provider firewall; the controller API stays loopback-only.")"
    users_export "$id";;
   3) users_engine list;;
   4)
    users_engine list
    prompt_read "$(L '用户 ID：' 'Account ID: ')" id || return 0
    prompt_read "$(L '总流量 GiB：' 'Total quota GiB: ')" quota || return 0
    confirm "$(L '只修改流量额度，保留到期时间和累计用量？' 'Change quota only, retaining expiry and usage?')" || continue
    users_engine quota "$id" "$quota";;
   5)
    users_engine list
    prompt_read "$(L '用户 ID：' 'Account ID: ')" id || return 0
    prompt_read "$(L '1 启用  2 禁用：' '1 Enable  2 Disable: ')" action || return 0
    case $action in 1) users_engine enable "$id" || return 1; if command -v ufw >/dev/null && LC_ALL=C ufw status | grep -q '^Status: active'; then users_firewall_allow "$id"; fi;; 2) users_engine disable "$id";; *) return 1;; esac;;
   6|7)
    users_engine list
    prompt_read "$(L '用户 ID：' 'Account ID: ')" id || return 0
    confirm "$(L '确认删除用户或重置其累计流量？' 'Confirm deleting the account or resetting its cumulative usage?')" || continue
    if [[ $choice == 6 ]]; then users_engine delete "$id"; else users_engine reset "$id"; fi;;
   8)
    prompt_read "$(L '最多用户数（1-100）：' 'Maximum accounts (1-100): ')" max || return 0
    users_engine limit "$max";;
   9)
    users_engine list
    prompt_read "$(L '用户 ID：' 'Account ID: ')" id || return 0
    users_export "$id" && users_qr "$id";;
   10) systemctl --no-pager status skybyte-users.service || :; users_engine list;;
   11) users_engine service on && users_start;;
   13)
    users_engine list
    prompt_read "$(L '用户 ID：' 'Account ID: ')" id || return 0
    prompt_read "$(L '从现在起有效天数：' 'Validity days from now: ')" days || return 0
    confirm "$(L '从现在重新设置有效期，保留额度和累计用量？' 'Set validity from now, retaining quota and usage?')" || continue
    users_engine validity "$id" "$days";;
   14) users_diagnostics;;
   15) resource_info;;
   12) if confirm "$(L '停止全部受限用户节点？' 'Stop all quota-managed user nodes?')"; then users_engine service off && users_stop; fi;;
   *) err "$(L '无效选项' 'Invalid selection')";;
  esac
 done
}


# Argo is an add-on to an existing managed deployment; its loopback origin is separate.
argo_state(){
 python3 - "$BASE/argo-state.json" "$1" <<'PY'
import json,sys
print(json.load(open(sys.argv[1])).get(sys.argv[2],''))
PY
}
argo_guard(){
 local unit marker expected
 for unit in skybyte-argo-node.service skybyte-argo-tunnel.service; do
  marker="Description=SKYBYTE managed $unit"
  if [[ $unit == skybyte-argo-node.service ]]; then expected="ExecStart=$BIN run -c $BASE/argo-server.json"; else expected="ExecStart=/bin/bash $MANAGER_BIN --argo-run"; fi
  if [[ -e $SYSTEMD_DIR/$unit || -L $SYSTEMD_DIR/$unit ]]; then
   if [[ ! -f $SYSTEMD_DIR/$unit || -L $SYSTEMD_DIR/$unit ]] || ! grep -Fxq "$marker" "$SYSTEMD_DIR/$unit" || ! grep -Fxq "$expected" "$SYSTEMD_DIR/$unit"; then err "$(L 'Argo 服务归属异常，拒绝修改' 'Argo unit ownership mismatch; refusing changes')"; return 1; fi
  fi
 done
 for unit in argo-state.json argo-server.json argo-empty.yml argo.token cloudflared; do
  [[ ! -L $BASE/$unit ]] || { err "$(L 'Argo 文件是符号链接，拒绝修改' 'Argo file is a symlink; refusing changes')"; return 1; }
 done
}
download_cloudflared(){
 local target=$1 tmp arch tag asset digest
 case "$(uname -m)" in x86_64) arch=amd64;; aarch64|arm64) arch=arm64;; *) return 1;; esac
 tmp=$(mktemp -d) || return 1
 curl -fsSL --retry 2 --max-time 30 https://api.github.com/repos/cloudflare/cloudflared/releases/latest -o "$tmp/release.json" || { rm -rf "$tmp"; return 1; }
 tag=$(python3 -c 'import json,sys; r=json.load(open(sys.argv[1])); assert not r["prerelease"] and not r["draft"]; print(r["tag_name"])' "$tmp/release.json") || { rm -rf "$tmp"; return 1; }
 [[ $tag =~ ^[0-9]{4}\.[0-9]+\.[0-9]+$ ]] || { rm -rf "$tmp"; return 1; }
 asset="cloudflared-linux-$arch"
 digest=$(python3 - "$tmp/release.json" "$asset" <<'PY'
import json,sys
asset=next(a for a in json.load(open(sys.argv[1]))['assets'] if a['name']==sys.argv[2])
digest=asset.get('digest') or ''; assert digest.startswith('sha256:')
print(digest.split(':',1)[1])
PY
 ) || { rm -rf "$tmp"; return 1; }
 if [[ ! $digest =~ ^[a-fA-F0-9]{64}$ ]] ||
    ! curl -fsSL --retry 2 --max-time 180 "https://github.com/cloudflare/cloudflared/releases/download/$tag/$asset" -o "$tmp/binary" ||
    ! printf '%s  %s\n' "$digest" "$tmp/binary" | sha256sum -c - >/dev/null; then rm -rf "$tmp"; return 1; fi
 command install -m 755 "$tmp/binary" "$target"
 local rc=$?; rm -rf "$tmp"; return "$rc"
}
argo_validate_domain(){
 python3 - "$1" <<'PY'
import re,sys
name=sys.argv[1]
assert len(name)<=253 and '.' in name and not re.fullmatch(r'[0-9.]+',name)
assert all(re.fullmatch(r'[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?',p) for p in name.split('.'))
PY
}
argo_write_config(){
 python3 - "$1" "$2" "$3" "$4" "$5" <<'PY'
import json,pathlib,secrets,sys,uuid
root,mode,domain,port,name=sys.argv[1:];root=pathlib.Path(root)
assert mode in ('quick','named') and 1024<=int(port)<=65535
uid=str(uuid.uuid4());path='/'+secrets.token_hex(16)
config={'log':{'level':'warn'},'inbounds':[{'type':'vless','tag':'argo-ws','listen':'127.0.0.1','listen_port':int(port),'users':[{'uuid':uid}], 'transport':{'type':'ws','path':path}}], 'outbounds':[{'type':'direct','tag':'direct'}], 'route':{'final':'direct'}}
state={'mode':mode,'domain':domain,'port':int(port),'path':path,'node_name':name,'connected':False}
(root/'argo-server.json').write_text(json.dumps(config,indent=2))
(root/'argo-state.json').write_text(json.dumps(state,ensure_ascii=False,indent=2))
(root/'argo-empty.yml').write_text('{}\n')
PY
}
argo_setup_units(){
 argo_guard || return 1
 if [[ -L $MANAGER_BIN ]]; then err "$(L '管理脚本不能是符号链接' 'Manager executable cannot be a symlink')"; return 1; fi
 if [[ -e $MANAGER_BIN ]] && ! grep -q '^# SKYBYTE Manager V2.1 community manager;' "$MANAGER_BIN"; then err "$(L '管理脚本路径被其他程序占用' 'Manager executable path is occupied')"; return 1; fi
 if [[ ! $SCRIPT_PATH -ef $MANAGER_BIN ]]; then command install -m 700 "$SCRIPT_PATH" "$MANAGER_BIN" || return 1; fi
 cat >"$SYSTEMD_DIR/skybyte-argo-node.service" <<EOF
[Unit]
Description=SKYBYTE managed skybyte-argo-node.service
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=$BIN run -c $BASE/argo-server.json
Restart=on-failure
RestartSec=3
[Install]
WantedBy=multi-user.target
EOF
 cat >"$SYSTEMD_DIR/skybyte-argo-tunnel.service" <<EOF
[Unit]
Description=SKYBYTE managed skybyte-argo-tunnel.service
After=network-online.target skybyte-argo-node.service
Requires=skybyte-argo-node.service
[Service]
ExecStart=/bin/bash $MANAGER_BIN --argo-run
Restart=on-failure
RestartSec=5
KillMode=control-group
TimeoutStopSec=15
[Install]
WantedBy=multi-user.target
EOF
 systemctl daemon-reload
}
argo_wait(){
 local attempt
 for ((attempt=0; attempt<30; attempt++)); do
  [[ $(argo_state connected) == True ]] && return 0
  systemctl is-active --quiet skybyte-argo-tunnel.service || return 1
  sleep 1
 done
 return 1
}
argo_install(){
 need_root; check_owned || return 1; argo_guard || return 1
 local mode=$1 port name domain='' token='' stage snap file
 [[ $mode == quick || $mode == named ]] || return 1
 for file in argo-state.json argo-server.json argo.token argo-empty.yml cloudflared; do
  [[ ! -e $BASE/$file ]] || { err "$(L '已有 Argo 文件；请先用 Argo 管理入口卸载' 'Argo files exist; remove via Argo controls first')"; return 1; }
 done
 for file in skybyte-argo-node.service skybyte-argo-tunnel.service; do
  [[ ! -e $SYSTEMD_DIR/$file ]] || return 1
  if systemctl list-unit-files "$file" --no-legend 2>/dev/null | grep -q "$file"; then err "$(L '已有同名 Argo 服务，拒绝覆盖' 'An Argo service with this name exists; refusing overwrite')"; return 1; fi
 done
 warn "$(L '新增 VLESS+WS 隧道节点；Cloudflare 终止公网 TLS，可处理隧道流量。临时隧道仅供测试，重启会换地址。' 'Adds a VLESS+WS node. Cloudflare terminates public TLS and can process tunnel traffic. Quick tunnels are for testing; restarts change the hostname.')"
 confirm "$(L '安装所选 Argo 模式？' 'Install selected Argo mode?')" || return 0
 prompt_read "$(L '本机 WS 端口 [8080]：' 'Local WS port [8080]: ')" port || return 1
 port=${port:-8080}; valid_port "$port" && (( 10#$port>=1024 )) || return 1; port=$((10#$port))
 if ss -H -ltn "( sport = :$port )" | grep -q .; then err "$(L '端口已占用' 'Port is occupied')"; return 1; fi
 name=$(choose_node_name) || return 1
 if [[ $mode == named ]]; then
  prompt_read "$(L 'Cloudflare 固定公开域名：' 'Cloudflare published hostname: ')" domain || return 1
  argo_validate_domain "$domain" || { err "$(L '域名格式无效' 'Invalid hostname')"; return 1; }
  say "请在 Cloudflare 控制台将该域名的 HTTP 服务指向 http://127.0.0.1:${port}；需要支持 WebSocket，不能要求交互式 Access 登录。" "In Cloudflare, route this hostname to HTTP http://127.0.0.1:$port with WebSocket support; interactive Access login is incompatible."
  prompt_read "$(L 'Tunnel Token（隐藏输入）：' 'Tunnel Token (hidden input): ')" token secret || return 1; printf '\n'
  if [[ ! $token =~ ^[a-zA-Z0-9+/=_-]+$ ]] || (( ${#token}<20 || ${#token}>4096 )); then err "$(L 'Token 格式无效' 'Invalid token format')"; return 1; fi
 fi
 snap=$(backup) || return 1
 stage=$(mktemp -d "$BASE/.argo-install.XXXXXX") || return 1
 if ! argo_write_config "$stage" "$mode" "$domain" "$port" "$name" || ! "$BIN" check -c "$stage/argo-server.json" || ! download_cloudflared "$stage/cloudflared"; then rm -rf "$stage"; return 1; fi
 if [[ $mode == named ]]; then printf '%s' "$token" >"$stage/argo.token"; token=''; fi
 chmod 600 "$stage"/argo-*; chmod 755 "$stage/cloudflared"
 for file in argo-state.json argo-server.json argo-empty.yml cloudflared argo.token; do
  if [[ -f $stage/$file ]]; then mv "$stage/$file" "$BASE/$file" || { rm -rf "$stage"; return 1; }; fi
 done
 rmdir "$stage"
 if ! argo_setup_units || ! systemctl enable --now skybyte-argo-node.service || ! systemctl enable --now skybyte-argo-tunnel.service; then
  err "$(L 'Argo 启动失败；保留配置供诊断，原节点配置未改变' 'Argo startup failed; config retained for diagnosis. Existing node config was not changed')"; return 1
 fi
 if ! argo_wait; then warn "$(L '隧道尚未注册连接；请使用 Argo 状态检查 Token、路由或出站网络。' 'Tunnel not registered yet; use Argo status to check token, route or outbound connectivity.')"; return 1; fi
 ok "$(L 'Argo 已启动；安装前备份：' 'Argo started; pre-install backup: ')$snap"
 exports
}
argo_run(){
 # Worker mode never takes the interactive manager lock. Only state/exports use their own locks.
 python3 - "$BASE" "$MANAGER_BIN" <<'PY'
import fcntl,json,os,pathlib,re,signal,subprocess,sys,tempfile
base=pathlib.Path(sys.argv[1]);runner=sys.argv[2];state_path=base/'argo-state.json'
def update(**fields):
 with open(base/'argo-state.lock','a') as lock:
  fcntl.flock(lock,fcntl.LOCK_EX)
  if not state_path.exists():return
  state=json.loads(state_path.read_text());state.update(fields)
  with tempfile.NamedTemporaryFile(mode='w',dir=base,delete=False) as tmp:
   json.dump(state,tmp,ensure_ascii=False,indent=2);name=tmp.name
  os.chmod(name,0o600);os.replace(name,state_path)
def sync():
 try:subprocess.run(['/bin/bash',runner,'--argo-export'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=20,check=False)
 except (OSError,subprocess.TimeoutExpired):pass
state=json.loads(state_path.read_text());mode=state['mode']
assert mode in ('quick','named')
common=[str(base/'cloudflared'),'tunnel','--config',str(base/'argo-empty.yml'),'--no-autoupdate','--grace-period','5s','--protocol','auto']
if mode=='quick':
 update(domain='',connected=False,last_error='');command=common+['--url',f"http://127.0.0.1:{state['port']}"]
else:
 assert (base/'argo.token').is_file();update(connected=False,last_error='')
 command=common+['run','--token-file',str(base/'argo.token')]
sync()
# Do not inherit incidental shell tokens/configuration from the interactive environment.
env={k:v for k,v in os.environ.items() if not k.startswith(('TUNNEL_','CF_'))}
proc=subprocess.Popen(command,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,env=env)
stopping=False;hostname=state.get('domain','') if mode=='named' else '';registered=False
pattern=re.compile(r'https://([a-z0-9]+(?:-[a-z0-9]+)*\.trycloudflare\.com)(?![a-z0-9.-])')
def stop(*_):
 global stopping
 stopping=True;proc.terminate()
 try:proc.wait(timeout=7)
 except subprocess.TimeoutExpired:proc.kill()
signal.signal(signal.SIGTERM,stop);signal.signal(signal.SIGINT,stop)
try:
 for line in proc.stdout:
  match=pattern.search(line)
  if mode=='quick' and match:hostname=match.group(1)
  lower=line.lower()
  if 'invalid tunnel token' in lower or 'unauthorized' in lower: update(last_error='token_or_account')
  elif 'timeout' in lower or 'failed to dial' in lower or 'network is unreachable' in lower: update(last_error='outbound_network')
  elif 'certificate' in lower and ('error' in lower or 'failed' in lower): update(last_error='tls')
  if 'Registered tunnel connection' in line:registered=True
  if registered and hostname:
   update(domain=hostname,connected=True,last_error='');sync();registered=False
 # Suppress raw cloudflared output: it can include operational/account information.
finally:
 if proc.poll() is None:stop()
 update(connected=False,**({'domain':''} if mode=='quick' else {}));sync()
rc=proc.wait();sys.exit(0 if stopping else rc if rc>0 else 1)
PY
}
argo_status(){
 [[ -f $BASE/argo-state.json ]] || { say '尚未配置 Argo 隧道。' 'Argo is not configured.'; return 0; }
 local mode domain port connected
 say "最近错误类别：$(argo_state last_error)" "Last error category: $(argo_state last_error)"
 mode=$(argo_state mode); domain=$(argo_state domain); port=$(argo_state port); connected=$(argo_state connected)
 say "模式：${mode}；公开域名：${domain:-尚未分配}；本机端口：${port}；已注册：$connected" "Mode: $mode; hostname: ${domain:-not assigned}; local port: $port; registered: $connected"
 if systemctl is-active --quiet skybyte-argo-node.service; then ok "$(L 'Argo WS 服务运行中' 'Argo WS origin active')"; else err "$(L 'Argo WS 服务未运行' 'Argo WS origin inactive')"; fi
 if systemctl is-active --quiet skybyte-argo-tunnel.service; then ok "$(L 'Argo 隧道服务运行中' 'Argo tunnel worker active')"; else err "$(L 'Argo 隧道服务未运行' 'Argo tunnel worker inactive')"; fi
 warn "$(L '服务运行不代表客户端可达；固定模式还需核对 Cloudflare 公开路由和客户端 SNI/WS 路径。' 'Active services do not prove client connectivity; verify published routes and client SNI/WS paths.')"
}
argo_clear_ready(){
 [[ -f $BASE/argo-state.json ]] || return 0
 python3 - "$BASE" <<'PY'
import fcntl,json,os,pathlib,tempfile,sys
base=pathlib.Path(sys.argv[1]);p=base/'argo-state.json'
with open(base/'argo-state.lock','a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX);s=json.loads(p.read_text());s['connected']=False
 if s['mode']=='quick':s['domain']=''
 with tempfile.NamedTemporaryFile(mode='w',dir=base,delete=False) as f:json.dump(s,f,indent=2);tmp=f.name
 os.chmod(tmp,0o600);os.replace(tmp,p)
PY
}
argo_stop(){
 argo_guard || return 1
 if [[ -f $SYSTEMD_DIR/skybyte-argo-tunnel.service ]]; then systemctl stop skybyte-argo-tunnel.service || return 1; fi
 if [[ -f $SYSTEMD_DIR/skybyte-argo-node.service ]]; then systemctl stop skybyte-argo-node.service || return 1; fi
 argo_clear_ready
}
argo_start(){
 [[ -f $BASE/argo-state.json ]] || return 1
 argo_setup_units || return 1
 "$BIN" check -c "$BASE/argo-server.json" || return 1
 systemctl start skybyte-argo-node.service || return 1
 systemctl start skybyte-argo-tunnel.service || return 1
 argo_wait || { err "$(L '隧道连接未就绪，请检查状态' 'Tunnel connection not ready; inspect status')"; return 1; }
 exports
}
argo_remove_internal(){
 argo_guard || return 1
 if [[ -f $SYSTEMD_DIR/skybyte-argo-tunnel.service ]]; then systemctl disable --now skybyte-argo-tunnel.service || return 1; fi
 if [[ -f $SYSTEMD_DIR/skybyte-argo-node.service ]]; then systemctl disable --now skybyte-argo-node.service || return 1; fi
 for file in argo-state.json argo-server.json argo-empty.yml argo.token cloudflared; do rm -f -- "$BASE/$file"; done
 rm -f -- "$SYSTEMD_DIR/skybyte-argo-node.service" "$SYSTEMD_DIR/skybyte-argo-tunnel.service"
 systemctl daemon-reload
}
argo_remove(){
 [[ -f $BASE/argo-state.json ]] || return 0
 argo_guard || return 1
 confirm "$(L '备份后卸载本机 Argo 附加节点？Cloudflare 账户内的隧道和 DNS 不会删除。' 'Back up and remove the local Argo add-on? Cloudflare tunnel/DNS records will not be deleted.')" || return 0
 local snap; snap=$(backup) || return 1
 argo_remove_internal || return 1
 ok "$(L 'Argo 已卸载；备份：' 'Argo removed; backup: ')$snap"
 exports
}
argo_restore_snapshot(){
 local path=$1 file
 argo_guard || return 1
 if [[ ! -f $path/argo-state.json ]]; then
  [[ ! -f $BASE/argo-state.json ]] || argo_remove_internal || return 1
  return 0
 fi
 [[ -f $path/argo-server.json && -f $path/cloudflared.bin ]] || return 1
 "$BIN" check -c "$path/argo-server.json" || return 1
 argo_stop || return 1
 for file in argo-state.json argo-server.json argo-empty.yml argo.token; do
  if [[ -f $path/$file ]]; then cp "$path/$file" "$BASE/$file" || return 1; chmod 600 "$BASE/$file"; else rm -f -- "$BASE/$file"; fi
 done
 command install -m 755 "$path/cloudflared.bin" "$BASE/cloudflared" || return 1
 argo_clear_ready || return 1
 argo_setup_units || return 1
 systemctl enable --now skybyte-argo-node.service || return 1
 systemctl enable --now skybyte-argo-tunnel.service || return 1
}
argo_manager(){
 local choice
 prompt_options '1 临时隧道  2 固定隧道  3 状态  4 启动  5 停止  6 重启  7 刷新节点  8 卸载 Argo  0 返回' '1 Quick  2 Named  3 Status  4 Start  5 Stop  6 Restart  7 Refresh nodes  8 Remove Argo  0 Back'
 prompt_read '> ' choice || return 0
 case $choice in
  1) argo_install quick;; 2) argo_install named;; 3) argo_status;; 4) argo_start;;
  5) argo_stop && exports;; 6) argo_stop && argo_start;; 7) exports;; 8) argo_remove;; 0) return 0;; *) err "$(L '无效选项' 'Invalid choice')"; return 1;;
 esac
}

uninstall_manager(){
 certificate_guard || return 1
 users_guard || return 1
 need_root
 check_owned || return 1
 argo_guard || return 1
 local unit snap file description managed_certs
 unit="$SYSTEMD_DIR/sing-box.service"
 # Metadata alone is insufficient: refuse to remove another service or a replacement binary symlink.
 if [[ ! -f $unit || -L $unit || -L $BIN || -L $CONF || -L $META ]] ||
    ! grep -Fxq 'Description=sing-box (managed by singbox-v2)' "$unit" ||
    ! grep -Fxq "ExecStart=$BIN run -c $CONF" "$unit"; then
  err "$(L '服务不属于本工具或已被修改，拒绝卸载' 'Service is not owned by this manager or has changed; refusing uninstall')"; return 1
 fi
 for file in singbox-v2-update.service singbox-v2-update.timer singbox-v2-hop.service; do
  case $file in
   singbox-v2-update.service) description='Description=sing-box v2 weekly update';;
   singbox-v2-update.timer) description='Description=sing-box v2 weekly update timer';;
   singbox-v2-hop.service) description='Description=singbox V2 HY2 IPv4 port hopping';;
  esac
  if [[ -e $SYSTEMD_DIR/$file || -L $SYSTEMD_DIR/$file ]]; then
   if [[ -L $SYSTEMD_DIR/$file ]] || ! grep -Fxq "$description" "$SYSTEMD_DIR/$file"; then
    err "$(L "附属服务 $file 已修改，拒绝卸载" "Auxiliary unit $file has changed; refusing uninstall")"; return 1
   fi
  fi
 done
 warn "$(L '卸载将停止所有节点，删除本工具的服务、二进制、节点配置及订阅文件。' 'Uninstall stops all nodes and removes managed services, binary, node config and subscription exports.')"
 say '先自动备份并保留备份；外部证书、UFW 规则、BBR 设置和 vnStat 均保留。' 'A backup is created and retained; external certificates, UFW rules, BBR settings and vnStat are kept.'
 confirm "$(L '确认卸载 SKYBYTE Manager 与托管 sing-box？' 'Uninstall SKYBYTE Manager and managed sing-box?')" || return 0
 managed_certs=$(python3 - "$META" "$CONF" <<'PY'
import json,sys,pathlib
s=json.load(open(sys.argv[1])); root=pathlib.Path(sys.argv[2]).parent
paths=s.get('managed_certificates',[])
# Legacy generated self-signed certificates have a known managed pathname and mode.
if 'managed_certificates' not in s and s.get('cert_mode')=='1' and s.get('cert_path')==str(root/'hy2-selfsigned.crt'):
 paths=[str(root/'hy2-selfsigned.crt'),str(root/'hy2-selfsigned.key')]
allowed={'hy2-selfsigned.crt','hy2-selfsigned.key','hy2-backup.crt','hy2-backup.key'}
for value in paths:
 p=pathlib.Path(value)
 if p.parent==root and p.name in allowed: print(p)
PY
 ) || return 1
 snap=$(backup) || { err "$(L '备份失败，已取消卸载' 'Backup failed; uninstall cancelled')"; return 1; }
 users_stop || return 1
 if [[ -f $BASE/users.json ]]; then users_engine ledger "$snap" || return 1; fi
 users_remove || return 1
 if [[ -f $BASE/argo-state.json ]]; then argo_remove_internal || return 1; fi
 if [[ -f $SYSTEMD_DIR/singbox-v2-update.timer ]]; then systemctl disable --now singbox-v2-update.timer || return 1; fi
 if [[ -f $SYSTEMD_DIR/singbox-v2-update.service ]]; then systemctl stop singbox-v2-update.service || return 1; fi
 if [[ -f $SYSTEMD_DIR/singbox-v2-hop.service ]]; then systemctl disable --now singbox-v2-hop.service || return 1; fi
 if [[ -f $SYSTEMD_DIR/singbox-v2-hop.service ]] && command -v nft >/dev/null && nft list table ip singbox_v2_hop >/dev/null 2>&1; then nft delete table ip singbox_v2_hop || return 1; fi
 if [[ -f $SYSTEMD_DIR/skybyte-certificate.timer ]]; then systemctl disable --now skybyte-certificate.timer || return 1; fi
 if [[ -f $SYSTEMD_DIR/skybyte-certificate.service ]]; then systemctl stop skybyte-certificate.service || return 1; fi
 rm -f "$SYSTEMD_DIR/skybyte-certificate.timer" "$SYSTEMD_DIR/skybyte-certificate.service" "$BASE/certificate-status.json"
 systemctl disable --now sing-box.service || return 1
 # Remove explicit managed files only; never recursively delete user configuration directories.
 rm -f -- "$unit" "$SYSTEMD_DIR/singbox-v2-update.service" "$SYSTEMD_DIR/singbox-v2-update.timer" "$SYSTEMD_DIR/singbox-v2-hop.service" "$BIN" "$CONF"
 while IFS= read -r file; do if [[ -n $file ]]; then rm -f -- "$file"; fi; done <<<"$managed_certs"
 for file in state.json language.conf hop.nft nodes.txt subscription-base64.txt v2rayn-nodes.txt v2rayn-subscription.txt shadowrocket-nodes.txt shadowrocket-subscription.txt shadowrocket-native-nodes.txt shadowrocket-native-subscription.txt sing-box-client.json clash-verge.yaml outbounds.json mihomo-proxies.yaml subscription-notes.txt hy2-client-ca.pem hy2-client-ca.cer hy2-client-ca.mobileconfig; do rm -f -- "$BASE/$file"; done
 # Remove executable copies only when they are identifiable manager scripts.
 for file in "$MANAGER_BIN" "$MANAGER_LIB"; do
  if [[ -f $file && ! -L $file ]] && grep -q '^# SKYBYTE Manager V2.1 community manager;' "$file"; then rm -f -- "$file"; fi
 done
 systemctl daemon-reload || return 1
 ok "$(L '卸载完成；备份保存在：' 'Uninstalled; backup retained at: ')$snap"
 warn "$(L 'UFW 放行规则、BBR 设置和备份中的私钥仍保留，请按需要人工管理。' 'UFW allow rules, BBR settings and backup private keys remain; manage them as needed.')"
}
# Manager updates affect script copies, never node credentials or configurations.
manager_latest(){
 local target=$1
 curl -fsSL --retry 2 --connect-timeout 10 --max-time 30 https://api.github.com/repos/skylink9119/sing-box-v2/releases/latest -o "$target" || return 1
 python3 - "$target" <<'PY'
import json,re,sys
r=json.load(open(sys.argv[1]));tag=r['tag_name']
assert not r.get('draft') and not r.get('prerelease') and re.fullmatch(r'v[0-9]+\.[0-9]+\.[0-9]+',tag)
a=next(a for a in r['assets'] if a['name']=='singbox-v2.sh')
assert re.fullmatch(r'sha256:[a-fA-F0-9]{64}',a.get('digest',''))
print(tag[1:])
PY
}
manager_update_apply(){
 local candidate=$1 version=$2 snapshot=$3 path active=false tunnel=false rc=0 stage
 local -a targets=("$MANAGER_LIB")
 for path in "$MANAGER_LIB" "$MANAGER_BIN"; do
  [[ ! -L $path ]] || { err "$(L '管理脚本是符号链接，拒绝覆盖' 'Refusing manager symlink')"; return 1; }
  if [[ -e $path ]]; then
   grep -q '^# SKYBYTE Manager V2.1 community manager;' "$path" || { err "$(L '管理脚本归属异常' 'Manager ownership mismatch')"; return 1; }
   if [[ $path != "$MANAGER_LIB" ]]; then targets+=("$path"); fi
  fi
 done
 bash -n "$candidate" && [[ $(bash "$candidate" --self-check) == "$version" ]] || return 1
 users_guard && argo_guard || return 1
 mkdir -m 700 "$snapshot" || return 1
 for path in "${targets[@]}"; do
  if [[ -f $path ]]; then cp -p "$path" "$snapshot/$(basename "$path")" || return 1; fi
 done
 if [[ -f $BASE/users.json ]] && systemctl is-active --quiet skybyte-users.service; then active=true; users_stop || return 1; fi
 if [[ -f $BASE/argo-state.json ]] && systemctl is-active --quiet skybyte-argo-tunnel.service; then tunnel=true; systemctl stop skybyte-argo-tunnel.service || { [[ $active != true ]] || users_start; return 1; }; fi
 for path in "${targets[@]}"; do
  mkdir -p "$(dirname "$path")" || { rc=1; break; }
  # Rename within the target filesystem, including when the running script is replaced.
  stage=$(mktemp "$path.stage.XXXXXX") || { rc=1; break; }
  if ! command install -m 700 "$candidate" "$stage" || ! mv -f "$stage" "$path"; then rm -f "$stage"; rc=1; break; fi
 done
 if [[ $rc == 0 && $active == true ]]; then systemctl start skybyte-users.service && systemctl is-active --quiet skybyte-users.service || rc=1; fi
 if [[ $rc == 0 && $tunnel == true ]]; then systemctl start skybyte-argo-tunnel.service && systemctl is-active --quiet skybyte-argo-tunnel.service || rc=1; fi
 if [[ $rc != 0 ]]; then
  [[ $active != true ]] || systemctl stop skybyte-users.service || :
  [[ $tunnel != true ]] || systemctl stop skybyte-argo-tunnel.service || :
  for path in "${targets[@]}"; do
   if [[ -f $snapshot/$(basename "$path") ]]; then command install -m 700 "$snapshot/$(basename "$path")" "$path" || return 1; else rm -f "$path"; fi
  done
  [[ $active != true ]] || systemctl start skybyte-users.service || :
  [[ $tunnel != true ]] || systemctl start skybyte-argo-tunnel.service || :
  err "$(L '管理脚本更新失败，已回滚脚本' 'Manager update failed; script copies rolled back')"; return 1
 fi
 ok "$(L '管理脚本更新完成：' 'Manager updated: ')v$version"
 say "脚本备份：$snapshot" "Script backup: $snapshot"
}
manager_update(){
 local tmp version digest snapshot rc
 require_cmd curl && require_cmd python3 || return 1
 tmp=$(mktemp -d "$BASE/manager-update.XXXXXX") || return 1
 version=$(manager_latest "$tmp/release.json") || { rm -rf "$tmp"; return 1; }
 say "管理脚本：v$MANAGER_VERSION → v$version" "Manager: v$MANAGER_VERSION → v$version"
 if [[ $MANAGER_VERSION == "$version" ]]; then rm -rf "$tmp"; ok "$(L '已是最新发布版' 'Already on the latest release')"; return 0; fi
 if ! python3 - "$MANAGER_VERSION" "$version" <<'PY'
import sys
sys.exit(0 if tuple(map(int,sys.argv[2].split('.')))>tuple(map(int,sys.argv[1].split('.'))) else 1)
PY
 then rm -rf "$tmp"; warn "$(L '当前版本更新，不自动降级' 'Current version is newer; refusing downgrade')"; return 0; fi
 confirm "$(L '更新管理脚本？受限用户和 Argo 隧道会短暂重启。' 'Update manager? Quota users and Argo tunnel briefly restart.')" || { rm -rf "$tmp"; return 0; }
 digest=$(python3 - "$tmp/release.json" <<'PY'
import json,sys
print(next(a['digest'][7:] for a in json.load(open(sys.argv[1]))['assets'] if a['name']=='singbox-v2.sh'))
PY
 ) || { rm -rf "$tmp"; return 1; }
 if ! curl -fsSL --retry 2 --max-time 120 "https://github.com/skylink9119/sing-box-v2/releases/download/v$version/singbox-v2.sh" -o "$tmp/candidate" ||
    ! python3 - "$tmp/candidate" "$digest" <<'PY'
import hashlib,sys
sys.exit(0 if hashlib.sha256(open(sys.argv[1],'rb').read()).hexdigest()==sys.argv[2].lower() else 1)
PY
 then rm -rf "$tmp"; err "$(L '下载或 SHA256 验证失败' 'Download or SHA256 verification failed')"; return 1; fi
 mkdir -p "$BASE/manager-backups"
 snapshot="$BASE/manager-backups/$(date +%Y%m%d-%H%M%S)-$RANDOM"
 rc=0; manager_update_apply "$tmp/candidate" "$version" "$snapshot" || rc=$?
 rm -rf "$tmp"; return "$rc"
}
users_summary(){
 if [[ -f $BASE/users.json ]]; then
  users_engine summary || warn "$(L '用户数据异常，请进入用户诊断' 'Invalid user data; open diagnostics')"
  startup_service_info "$(L '用户配额服务' 'User quota supervisor')" true skybyte-users.service
 else say '用户管理：尚未初始化' 'User management: not initialized'; fi
}
users_diagnostics(){
 users_guard || return 1
 users_engine diagnose
 say '恢复步骤：修复配置/端口冲突后，选择启用用户；服务未启动时选择启动用户服务。' 'Recovery: fix config/port conflicts, then enable the account; start the supervisor if inactive.'
 say '日志可能含节点地址，请在本机检查，不要公开完整日志。' 'Logs may contain node addresses; inspect locally and avoid publishing full logs.'
 systemctl --no-pager status skybyte-users.service || :
}
resource_info(){
 require_cmd ps || { say '请安装 procps 后重试' 'Install procps and retry'; return 1; }
 python3 - "$BASE" "$BIN" "${LANGUAGE_CHOICE:-zh_CN}" <<'PY'
import pathlib,subprocess,sys
base=pathlib.Path(sys.argv[1]);binary=sys.argv[2]
r=subprocess.run(['ps','-eo','pid=,rss=,args='],capture_output=True,text=True,check=True)
cores=users=total=user_rss=0
for line in r.stdout.splitlines():
 parts=line.split(None,2)
 if len(parts)!=3:continue
 pid,rss,args=parts
 if not args.startswith(binary+' run -c '):continue
 cores+=1;total+=int(rss)
 if args[len(binary+' run -c '):].startswith(str(base/'users')+'/'):
  users+=1;user_rss+=int(rss)
en=sys.argv[3]=='en_US'
print(('sing-box processes / RSS: ' if en else 'sing-box 进程数 / RSS：')+f'{cores} / {total/1024:.1f} MiB')
print(('Quota user processes / RSS: ' if en else '受限用户进程数 / RSS：')+f'{users} / {user_rss/1024:.1f} MiB')
p=pathlib.Path('/proc/meminfo')
if p.exists():
 m={line.split(':')[0]:int(line.split()[1]) for line in p.read_text().splitlines() if line.split()[1].isdigit()}
 print(('System available / total RAM: ' if en else '系统可用 / 总内存：')+f"{m.get('MemAvailable',0)/1024:.1f} / {m['MemTotal']/1024:.1f} MiB")
p=pathlib.Path('/proc/loadavg')
if p.exists():print(('Load (1/5/15 min): ' if en else '负载（1/5/15 分钟）：')+' '.join(p.read_text().split()[:3]))
print('RSS includes shared memory; this is a snapshot, not a capacity guarantee.' if en else 'RSS 含共享内存；这是当前快照，不能保证最大承载人数。')
PY
}
certificate_info(){
 [[ -f $CONF ]] || return 0
 require_cmd openssl || return 1
 python3 - "$CONF" "${LANGUAGE_CHOICE:-zh_CN}" <<'PY'
import datetime,json,ssl,subprocess,sys
cfg=json.load(open(sys.argv[1]));en=sys.argv[2]=='en_US'
for inbound in cfg.get('inbounds',[]):
 if inbound['type']!='hysteria2':continue
 path=inbound['tls']['certificate_path']
 r=subprocess.run(['openssl','x509','-in',path,'-noout','-enddate'],capture_output=True,text=True)
 if r.returncode:
  print('HY2 certificate unreadable' if en else 'HY2 证书无法读取');continue
 expiry=ssl.cert_time_to_seconds(r.stdout.strip().split('=',1)[1])
 days=int((expiry-datetime.datetime.now(datetime.timezone.utc).timestamp())//86400)
 print(('HY2 certificate days remaining: ' if en else 'HY2 证书剩余天数：')+str(days))
 if days<=30:print('WARNING: expired or expires within 30 days; renew and reload.' if en else '警告：证书已过期或将在 30 天内到期，请续签并重载。')
PY
}
certificate_guard(){
 local unit expected
 for unit in skybyte-certificate.service skybyte-certificate.timer; do
  expected='Description=SKYBYTE managed certificate monitor'
  if [[ -e $SYSTEMD_DIR/$unit || -L $SYSTEMD_DIR/$unit ]]; then
   if [[ -L $SYSTEMD_DIR/$unit ]] || ! grep -Fxq "$expected" "$SYSTEMD_DIR/$unit"; then err "$(L '证书服务归属异常' 'Certificate unit ownership mismatch')"; return 1; fi
   if [[ $unit == *.service ]]; then grep -Fxq "ExecStart=/bin/bash $MANAGER_BIN --certificate-check" "$SYSTEMD_DIR/$unit" || return 1; fi
  fi
 done
 [[ ! -L $BASE/certificate-status.json ]] || return 1
}
certificate_identity(){
 python3 - "$CONF" <<'PY'
import json,sys
for i in json.load(open(sys.argv[1]))['inbounds']:
 if i['type']=='hysteria2':
  t=i['tls'];print(t['certificate_path']);print(t['key_path']);print(t['server_name']);break
else:sys.exit(1)
PY
}
certificate_record(){
 python3 - "$BASE/certificate-status.json" "$1" <<'PY'
import json,os,pathlib,sys,tempfile
p=pathlib.Path(sys.argv[1]);assert not p.is_symlink()
fd,tmp=tempfile.mkstemp(dir=p.parent)
with os.fdopen(fd,'w') as f:json.dump({'fingerprint':sys.argv[2]},f);f.flush();os.fsync(f.fileno())
os.replace(tmp,p)
PY
}
certificate_reload(){
 check_owned && certificate_guard && users_guard || return 1
 local identity cert key name fingerprint snap active=false admin=false
 identity=$(certificate_identity) || return 1
 { IFS= read -r cert; IFS= read -r key; IFS= read -r name; } <<<"$identity"
 validate_certificate "$cert" "$key" "$name" && "$BIN" check -c "$CONF" || return 1
 fingerprint=$(openssl x509 -in "$cert" -noout -fingerprint -sha256) || return 1
 snap=$(backup) || return 1
 if systemctl is-active --quiet sing-box.service; then admin=true; fi
 if [[ -f $BASE/users.json ]] && systemctl is-active --quiet skybyte-users.service; then active=true; users_stop || return 1; fi
 if [[ -f $BASE/users.json ]]; then
  if ! users_engine certificates || ! users_engine validate "$BIN"; then users_restore_snapshot "$snap" || :; [[ $active == true ]] || users_stop || :; return 1; fi
 fi
 if { [[ $admin == true ]] && ! { systemctl restart sing-box.service && service_healthy; }; } ||
    { [[ $active == true ]] && ! { systemctl start skybyte-users.service && systemctl is-active --quiet skybyte-users.service; }; }; then
  [[ $active != true ]] || users_stop || :
  users_restore_snapshot "$snap" || :
  [[ $active == true ]] || users_stop || :
  err "$(L '重载失败，已尝试恢复用户证书；请检查主服务' 'Reload failed; attempted user certificate rollback; inspect main service')"; return 1
 fi
 exports >/dev/null || return 1
 if [[ -f $BASE/users.json ]]; then users_engine export_all | while IFS= read -r id; do users_export "$id" >/dev/null || return 1; done; fi
 certificate_record "$fingerprint" || return 1
 ok "$(L '证书已同步并重载原先运行的 HY2 服务' 'Certificate synchronized; previously running HY2 services reloaded')"
 warn "$(L '自签名证书更换后，客户端须重新核实并导入信任。' 'If a self-signed certificate changed, verify and re-import client trust.')"
}
certificate_check(){
 check_owned && certificate_guard || return 1
 certificate_info
 local identity cert key name fingerprint previous
 identity=$(certificate_identity) || return 0
 { IFS= read -r cert; IFS= read -r key; IFS= read -r name; } <<<"$identity"
 validate_certificate "$cert" "$key" "$name" || return 1
 fingerprint=$(openssl x509 -in "$cert" -noout -fingerprint -sha256) || return 1
 if [[ ! -f $BASE/certificate-status.json ]]; then certificate_record "$fingerprint"; return; fi
 previous=$(python3 - "$BASE/certificate-status.json" <<'PY'
import json,sys
print(json.load(open(sys.argv[1]))['fingerprint'])
PY
 ) || return 1
 [[ $fingerprint != "$previous" ]] || return 0
 if [[ $(state cert_mode) == 2 ]]; then certificate_reload; else warn "$(L '自签名证书已变化，请手动重载并更新客户端信任' 'Self-signed certificate changed; reload manually and update client trust')"; fi
}
certificate_menu(){
 check_owned && certificate_guard || return 1
 certificate_identity >/dev/null || { err "$(L '未安装 HY2' 'HY2 not installed')"; return 1; }
 local choice
 prompt_options '1 查看证书有效期  2 续签后同步并重载  3 开启每日检查  4 关闭每日检查  0 返回' '1 Expiry  2 Reload renewed certificate  3 Enable daily checks  4 Disable daily checks  0 Back'
 prompt_read '> ' choice || return 0
 case $choice in
  1) certificate_info;;
  2) confirm "$(L '同步证书并重启正在运行的 HY2 服务？' 'Sync certificates and restart active HY2 services?')" && certificate_reload;;
  3)
   users_guard setup || return 1
   certificate_check || return 1
   if [[ ! $SCRIPT_PATH -ef $MANAGER_BIN ]]; then command install -m 700 "$SCRIPT_PATH" "$MANAGER_BIN" || return 1; fi
   cat >"$SYSTEMD_DIR/skybyte-certificate.service" <<UNIT
[Unit]
Description=SKYBYTE managed certificate monitor
[Service]
Type=oneshot
ExecStart=/bin/bash $MANAGER_BIN --certificate-check
UMask=0077
UNIT
   cat >"$SYSTEMD_DIR/skybyte-certificate.timer" <<'UNIT'
[Unit]
Description=SKYBYTE managed certificate monitor
[Timer]
OnCalendar=daily
RandomizedDelaySec=15m
Persistent=true
[Install]
WantedBy=timers.target
UNIT
   systemctl daemon-reload && systemctl enable --now skybyte-certificate.timer
   say '检查不会申请证书。域名证书有效续签后会自动同步；可在续签工具中设置 --certificate-reload 钩子。' 'Checks do not issue certificates. Valid renewed domain certificates are synchronized; renewal tools can call --certificate-reload.';;
  4) if [[ -f $SYSTEMD_DIR/skybyte-certificate.timer ]]; then systemctl disable --now skybyte-certificate.timer; fi;;
  0) return 0;; *) return 1;;
 esac
}


manager_self_check(){
 python3 - "$SCRIPT_PATH" <<'PY_SELF_CHECK'
import pathlib,re,sys
s=pathlib.Path(sys.argv[1]).read_text()
for m in re.finditer(r"<<'(PY[^']*)'\n(.*?)\n\1(?:\n|$)",s,re.S):compile(m[2],m[1],'exec')
m=re.search(r'^MANAGER_VERSION=([0-9]+\.[0-9]+\.[0-9]+)$',s,re.M);assert m
assert '# SKYBYTE Manager V2.1 community manager;' in s
print(m[1])
PY_SELF_CHECK
}
action_failed(){ err "$(L '操作失败；请检查上面的输出' 'Operation failed; inspect the output above')"; }
sub_menu(){
 local group=$1 choice
 MAIN_ACTION=""
 printf '%s\n----------------------------------------------\n' "$GREEN"
 case $group in
  1)
   say ' 1. 安装 Reality + Vision' ' 1. Install Reality + Vision'
   say ' 2. 安装 Hysteria2' ' 2. Install Hysteria2'
   say ' 3. 安装双协议' ' 3. Install both protocols'
   say ' 4. Argo 临时 / 固定隧道管理' ' 4. Argo Quick / Named Tunnel controls'
   ;;
  2)
   say ' 1. 查看节点与各客户端格式' ' 1. View nodes and client formats'
   say ' 2. 导出本地订阅' ' 2. Export local subscriptions'
   say ' 3. 自定义节点名称' ' 3. Customize node names'
   say ' 4. 小火箭节点二维码' ' 4. Shadowrocket node QR codes'
   say ' 5. 用户数量、流量与有效期管理' ' 5. Account limits, traffic quotas and expiry'
   ;;
  3)
   say ' 1. sing-box 状态与启停' ' 1. sing-box status and controls'
   say ' 2. 查看 sing-box 日志' ' 2. View sing-box logs'
   say ' 3. Argo 隧道状态' ' 3. Argo tunnel status'
   ;;
  4)
   say ' 1. 新服务器初始化' ' 1. Initialize new server'
   say ' 2. UFW 防火墙管理' ' 2. UFW controls'
   say ' 3. 检查防火墙规则' ' 3. Audit firewall rules'
   say ' 4. 启用 BBR + FQ' ' 4. Enable BBR + FQ'
   say ' 5. HY2 端口跳跃' ' 5. HY2 port hopping'
   say ' 6. VPS 流量统计（vnStat）' ' 6. VPS traffic (vnStat)'
   say ' 7. IP 信息' ' 7. IP information'
   say ' 8. 基础网络诊断' ' 8. Basic network checks'
   say ' 9. HY2 / 小火箭连接诊断' ' 9. HY2 / Shadowrocket checks'
   prompt_options '10. 进程、内存与负载' '10. Processes, memory and load'
   ;;
  5)
   say ' 1. 手动更新 sing-box' ' 1. Update sing-box'
   say ' 2. 每周自动更新' ' 2. Weekly automatic updates'
   say ' 3. 备份配置' ' 3. Back up configuration'
   say ' 4. 恢复配置' ' 4. Restore configuration'
   say ' 5. 检查 / 更新 SKYBYTE Manager 管理脚本' ' 5. Check / update SKYBYTE Manager script'
   say ' 6. HY2 证书检查与续签重载' ' 6. HY2 certificate checks and renewal reload'
   ;;
  6)
   say ' 1. 切换语言' ' 1. Change language'
   say ' 2. 法律与隐私声明' ' 2. Legal and privacy notice'
   say ' 3. 卸载 SKYBYTE Manager / sing-box' ' 3. Uninstall SKYBYTE Manager / sing-box'
   ;;
 esac
 say ' 0. 返回主菜单' ' 0. Back to main menu'
 printf -- '----------------------------------------------%s\n' "$RESET"
 prompt_read "$(L '请选择：' 'Select: ')" choice || return 1
 case "$group:$choice" in
  1:1) MAIN_ACTION=install_reality;;
  1:2) MAIN_ACTION=install_hy2;;
  1:3) MAIN_ACTION=install_dual;;
  1:4) MAIN_ACTION=argo;;
  2:1) MAIN_ACTION=nodes;;
  2:2) MAIN_ACTION=subscription;;
  2:3) MAIN_ACTION=rename;;
  2:4) MAIN_ACTION=qr;;
  2:5) MAIN_ACTION=users;;
  3:1) MAIN_ACTION=service;;
  3:2) MAIN_ACTION=logs;;
  3:3) MAIN_ACTION=argo_status;;
  4:1) MAIN_ACTION=initialize;;
  4:2) MAIN_ACTION=firewall;;
  4:3) MAIN_ACTION=audit;;
  4:4) MAIN_ACTION=bbr;;
  4:5) MAIN_ACTION=hop;;
  4:6) MAIN_ACTION=traffic;;
  4:7) MAIN_ACTION=ip;;
  4:8) MAIN_ACTION=network;;
  4:9) MAIN_ACTION=hy2_check;;
  4:10) MAIN_ACTION=resources;;
  5:1) MAIN_ACTION=update;;
  5:2) MAIN_ACTION=auto;;
  5:3) MAIN_ACTION=backup;;
  5:4) MAIN_ACTION=restore;;
  5:5) MAIN_ACTION=manager_update;;
  5:6) MAIN_ACTION=certificate;;
  6:1) MAIN_ACTION=language;;
  6:2) MAIN_ACTION=notice;;
  6:3) MAIN_ACTION=uninstall;;
  *:0) return 0;; *) err "$(L '无效选项' 'Invalid choice')";;
 esac
}
dispatch_action(){
 case $1 in
 install_reality) install_protocol 1;; install_hy2) install_protocol 2;; install_dual) install_protocol 3;;
 argo) argo_manager;; nodes) exports;; subscription) subscription;; rename) rename_node;; qr) shadowrocket_qr;; users) users_manager;;
 service) service_manager;; logs) journalctl -u sing-box -n 80 --no-pager;; argo_status) argo_status;;
 initialize) initialize_server;; firewall) firewall;; audit) firewall_audit;; bbr) bbr;; hop) hop;; traffic) traffic;;
 ip) ipcheck;; network) netcheck;; hy2_check) hy2_diagnostics;;
 manager_update) manager_update;; certificate) certificate_menu;; resources) resource_info;;
 update) update;; auto) configure_auto;; backup) backup;; restore) restore;;
 language) select_language && startup_info;; notice) notice;; uninstall) uninstall_manager;;
 esac
}
main(){
 need_root; require_cmd flock
 local group action_status
 startup_info
 while :; do
  printf '%s\n==============================================\n' "$CYAN"
  cat <<LOGO
   ███████╗██╗  ██╗██╗   ██╗██████╗ ██╗   ██╗████████╗███████╗
   ██╔════╝██║ ██╔╝╚██╗ ██╔╝██╔══██╗╚██╗ ██╔╝╚══██╔══╝██╔════╝
   ███████╗█████╔╝  ╚████╔╝ ██████╔╝ ╚████╔╝    ██║   █████╗
   ╚════██║██╔═██╗   ╚██╔╝  ██╔══██╗  ╚██╔╝     ██║   ██╔══╝
   ███████║██║  ██╗   ██║   ██████╔╝   ██║      ██║   ███████╗
   ╚══════╝╚═╝  ╚═╝   ╚═╝   ╚═════╝    ╚═╝      ╚═╝   ╚══════╝
                  SKYBYTE Manager v${MANAGER_VERSION}
                Reality · Hysteria2 · VPS
LOGO
  printf '==============================================%s\n' "$RESET"
  printf '%s' "$GREEN"
  say ' 1. 协议安装与 Argo 隧道' ' 1. Protocol installation and Argo tunnels'
  say ' 2. 节点与订阅' ' 2. Nodes and subscriptions'
  say ' 3. 服务与日志' ' 3. Services and logs'
  say ' 4. 服务器与网络' ' 4. Server and network'
  say ' 5. 更新与备份' ' 5. Updates and backups'
  say ' 6. 设置与卸载' ' 6. Settings and uninstall'
  say ' 7. 用户与配额管理' ' 7. Users and quotas'
  users_summary
  say ' 0. 退出' ' 0. Exit'
  printf '%s' "$RESET"
  printf '%sYouTube: %s%s\n' "$CYAN" "$YOUTUBE" "$RESET"
  prompt_read "$(L '请选择：' 'Select: ')" group || return 0
  [[ $group != 0 ]] || return 0
  case $group in 7) MAIN_ACTION=users;; 1|2|3|4|5|6) sub_menu "$group" || return 0;; *) err "$(L '无效选项' 'Invalid choice')"; continue;; esac
  [[ -n $MAIN_ACTION ]] || continue
  set +e
  ( set -Eeuo pipefail; trap action_failed ERR; dispatch_action "$MAIN_ACTION" )
  action_status=$?
  set -e
  if [[ $MAIN_ACTION == uninstall && $action_status == 0 && ! -e $META ]]; then return 0; fi
  if [[ $MAIN_ACTION == manager_update && $action_status == 0 && -f $MANAGER_LIB ]] && ! grep -Fxq "MANAGER_VERSION=$MANAGER_VERSION" "$MANAGER_LIB"; then exec 9>&-; exec bash "$MANAGER_LIB"; fi
  load_language
 done
}

bootstrap(){
 need_root
 require_cmd flock || return 1
 mkdir -p "$BASE" "$REPORT" "$BACKUP"; chmod 700 "$BASE" "$REPORT" "$BACKUP"
 exec 9>"$LOCK"; flock -n 9 || { err "$(L '其他管理任务正在运行' 'Another manager is running')"; return 1; }
 load_language
 if [[ -z $LANGUAGE_CHOICE ]]; then
  if [[ ${1:-} == --auto-update || ${1:-} == --certificate-check || ${1:-} == --certificate-reload || ${1:-} == --notice ]]; then LANGUAGE_CHOICE=en_US; else select_language || return 1; fi
 fi
 export LANGUAGE_CHOICE
}
if [[ ${BASH_SOURCE[0]} == "$0" ]]; then
 case ${1:-} in
  --self-check) manager_self_check; exit $?;;
  --users-watch) need_root; load_language; LANGUAGE_CHOICE=${LANGUAGE_CHOICE:-en_US}; users_engine watch; exit $?;;
  --argo-run) need_root; load_language; LANGUAGE_CHOICE=${LANGUAGE_CHOICE:-en_US}; argo_run; exit $?;;
  --argo-export) need_root; load_language; LANGUAGE_CHOICE=${LANGUAGE_CHOICE:-en_US}; exports; exit $?;;
 esac
 bootstrap "${1:-}" || exit 1
 case "${1:-}" in --auto-update) update_auto;; --certificate-check) certificate_check;; --certificate-reload) certificate_reload;; --notice) notice;; *) main;; esac
fi
